 switch(n){case 3:Values::first;break;default:Values::second;}
 if(n!=3)return 14;
 if(sizeof(Values::first)!=sizeof(int)||sizeof(&Values::first)!=sizeof(const int*)||!noexcept(Values::first))return 15;
 made=dead=calls=0;
