 if(&readonly(a)!=&a||&readonly(b)!=&a)return 4;
 int*p=&a,*q=&b;
 if(&pointerSlot(p)!=&p||&pointerSlot(q)!=&p)return 5;
 pointerSlot(q)=&b;if(p!=&b)return 6;
