TEST_F(TranslateTest, CoreV2NativeHeapAcceptsCheckedDirectDeclarations) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"malloc", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);void*f(Size n){return malloc(n);}"},
      {"calloc", "using Size=decltype(sizeof(0));extern \"C\" void*calloc(Size,Size);void*f(Size n){return calloc(n,4);}"},
      {"realloc", "using Size=decltype(sizeof(0));extern \"C\" void*realloc(void*,Size);void*f(void*p,Size n){return realloc(p,n);}"},
      {"realloc-null", "using Size=decltype(sizeof(0));extern \"C\" void*realloc(void*,Size);void*f(Size n){return realloc(nullptr,n);}"},
      {"realloc-zero", "using Size=decltype(sizeof(0));extern \"C\" void*realloc(void*,Size);void*f(void*p){return realloc(p,0);}"},
      {"free", "extern \"C\" void free(void*);void f(void*p){free(p);}"},
      {"free-null", "extern \"C\" void free(void*);void f(){free(nullptr);}"},
      {"declaration-only", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);int main(){return 0;}"},
      {"parenthesized", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);void*f(Size n){return (malloc)(n);}"},
      {"qualified", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);void*f(Size n){return (::malloc)(n);}"},
      {"sequenced-arguments", "using Size=decltype(sizeof(0));extern \"C\" void*calloc(Size,Size);void*f(Size n){return calloc(n++,n++);}"},
      {"conversion-argument", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);struct S{Size n;operator Size()const{return n;}};void*f(S n){return malloc(n);}"},
      {"default-argument-call", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);void*f(void*p=malloc(4)){return p;}void*g(){return f();}"},
      {"function-template", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);template<class T>void*f(T n){return malloc(n);}void*g(){return f(4u);}"},
      {"dead-call", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);int main(){if(false)malloc(4);return 0;}"},
      {"noexcept-call", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);bool f(){return noexcept(malloc(4));}"},
      {"const-parameter", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(const Size);void*f(Size n){return malloc(n);}"},
      {"noexcept-prototype", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size)noexcept;void*f(Size n){return malloc(n);}"},
      {"redeclarations", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);extern \"C\" void*malloc(Size);void*f(Size n){return malloc(n);}"},
      {"definition-wins", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);extern \"C\" void free(void*);unsigned char bytes[64]{};void*f(){void*p=malloc(4);free(p);return p;}extern \"C\" void*malloc(Size){return bytes;}extern \"C\" void free(void*){}"},
      {"realloc-definition-wins", "using Size=decltype(sizeof(0));extern \"C\" void*realloc(void*,Size);extern \"C\" void*realloc(void*p,Size){return p;}void*f(void*p){return realloc(p,4);}"},
      {"class-array", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);extern \"C\" void free(void*);struct R{int n;R():n(3){}~R(){}static void*operator new[](Size n)noexcept{return malloc(n);}static void operator delete[](void*p)noexcept{free(p);}};R*f(int n){return new R[n];}void g(R*p){delete[]p;}"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    auto Source = tmpFile("native-heap-" + Name + ".cpp");
    auto Output = tmpFile("native-heap-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    EXPECT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

TEST_F(TranslateTest, CoreV2NativeHeapRejectsUnverifiedDeclarationsAndFunctionValues) {
  const std::vector<std::tuple<std::string, std::string, std::string>> Cases = {
      {"cpp-linkage", "using Size=decltype(sizeof(0));void*malloc(Size);void*f(){return malloc(4);}", "TR0203"},
      {"wrong-argument", "extern \"C\" void*malloc(int);void*f(){return malloc(4);}", "TR0203"},
      {"wrong-result", "using Size=decltype(sizeof(0));extern \"C\" const void*malloc(Size);", "TR0203"},
      {"wrong-free-type", "extern \"C\" void free(const void*);void f(){free(nullptr);}", "TR0203"},
      {"wrong-arity", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size,Size);", "TR0203"},
      {"variadic", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size,...);", "TR0201"},
      {"namespace", "using Size=decltype(sizeof(0));namespace N{extern \"C\" void*malloc(Size);}void*f(){return N::malloc(4);}", "TR0201"},
      {"written-attribute", "using Size=decltype(sizeof(0));extern \"C\" __attribute__((used)) void*malloc(Size);", "TR0201"},
      {"written-size-attribute", "using Size=decltype(sizeof(0));extern \"C\" __attribute__((alloc_size(1))) void*malloc(Size);", "TR0201"},
      {"address", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);auto f(){return &malloc;}", "TR0201"},
      {"discarded-name", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);void f(){malloc;}", "TR0201"},
      {"noexcept-name", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);bool f(){return noexcept(malloc);}", "TR0201"},
      {"discarded-address", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);void f(){if constexpr(false){auto p=&malloc;}}", "TR0201"},
      {"composite-callee", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);void*f(){return (0,malloc)(4);}", "TR0201"},
      {"default-parameter", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size=4);void*f(){return malloc();}", "TR0201"},
      {"unsupported-argument", "using Size=decltype(sizeof(0));extern \"C\" void*malloc(Size);void*f(){return malloc(sizeof(long double));}", "TR0201"},
      {"unknown-function", "using Size=decltype(sizeof(0));extern \"C\" void*allocate(Size);void*f(){return allocate(4);}", "TR0203"},
      {"wrong-realloc-pointer", "using Size=decltype(sizeof(0));extern \"C\" void*realloc(const void*,Size);void*f(const void*p){return realloc(p,4);}", "TR0203"},
      {"wrong-realloc-size", "extern \"C\" void*realloc(void*,unsigned);void*f(void*p){return realloc(p,4);}", "TR0203"},
      {"written-realloc-size-attribute", "using Size=decltype(sizeof(0));extern \"C\" __attribute__((alloc_size(2))) void*realloc(void*,Size);", "TR0201"},
  };
  for (const auto &[Name, Code, Diagnostic] : Cases) {
    SCOPED_TRACE(Name);
    auto Source = tmpFile("native-heap-reject-" + Name + ".cpp");
    auto Output = tmpFile("native-heap-reject-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    expectCode(Result, Diagnostic);
    expectNoArtifacts(Output);
  }
}

TEST_F(TranslateTest, CoreV2NativeHeapInteroperatesWithAnIndependentCClient) {
  const auto Output = tmpFile("native-heap.nc");
  auto Result = translate(fixture("native-heap.cpp"),
                          {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Object = tmpFile("native-heap" + Optimization + ".o");
    // A function-only TU leaves ownership of the process allocator to main.
    auto Compile = ncc({Output.string(), Optimization, "-fno-lto", "-c",
                        "-fstrict-aliasing", "-o", Object.string()});
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    for (bool NativeCRT : {true, false}) {
      SCOPED_TRACE(NativeCRT ? "native CRT" : "default process allocator");
      const auto Executable = tmpFile("native-heap" + Optimization + (NativeCRT ? "-crt" : "-default"));
      std::vector<std::string> Arguments{fixture("native-heap-harness.c").string(),
          Object.string(), Optimization, "-fno-lto", "-fstrict-aliasing", "-o", Executable.string()};
      if (NativeCRT) Arguments.push_back("-fno-builtin-mimalloc");
      auto Link = ncc(Arguments);
      ASSERT_EQ(Link.exitCode, 0) << Link.out << Link.err;
      auto Run = exec(Executable.string(), {});
      EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
    }
  }
  auto Freestanding = ncc({Output.string(), "-fsyntax-only", "-ffreestanding"});
  EXPECT_NE(Freestanding.exitCode, 0);
  EXPECT_TRUE(Freestanding.stderrContains("translated native heap calls require a hosted native CRT"))
      << Freestanding.out << Freestanding.err;
}

TEST_F(TranslateTest, CoreV2AllocationAcceptsSourceDefinedFunctions) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"inherited-global-visibility", "using Size=decltype(sizeof(0));unsigned char bytes[64]{};void*operator new(Size);void*operator new(Size){return bytes;}void operator delete(void*)noexcept;void operator delete(void*)noexcept{}int*f(){return new int(3);}"},
      {"inherited-array-visibility", "using Size=decltype(sizeof(0));unsigned char bytes[64]{};void*operator new[](Size);void*operator new[](Size){return bytes;}void operator delete[](void*)noexcept;void operator delete[](void*)noexcept{}int*f(){return new int[2]{};}"},
      // Source-only compiler fixture: the enum stand-in does not supply an SDK.
      {"aligned-delete-protocol", "using Size=decltype(sizeof(0));\nnamespace std{enum class align_val_t:Size{};}\nstruct Aligned{int n;static void operator delete(void*p,std::align_val_t a)noexcept{}};\nstruct SizedAligned{int n;static void operator delete(void*p,Size n,std::align_val_t a)noexcept{}};\nvoid disposeAligned(Aligned*p){delete p;}\nvoid disposeSizedAligned(SizedAligned*p){delete p;}\n"},
      {"member-new-declaration", "using Size=decltype(sizeof(0));struct R{int n;static void*operator new(Size){return nullptr;}};"},
      {"member-delete-declaration", "struct R{int n;static void operator delete(void*){}};"},
      {"global-new-declaration", "using Size=decltype(sizeof(0));void*operator new(Size){return nullptr;}"},
      {"free-template-declaration", "template<class T>void*operator new(decltype(sizeof(0)),T*p){return p;}"},
      {"class-template-declaration", "template<class T>struct R{static void*operator new(decltype(sizeof(0))){return nullptr;}};"},
      {"scalar", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int f(){int*p=new int(3);int n=*p;delete p;return n;}"},
      {"default-scalar", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int f(){int*p=new int;*p=4;int n=*p;delete p;return n;}"},
      {"value-scalar", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int f(){int*p=new int();int n=*p;delete p;return n;}"},
      {"const-scalar", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int f(){const int*p=new const int(3);int n=*p;delete p;return n;}"},
      {"pointer-object", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int f(){using P=int*;P*p=new P(nullptr);bool b=*p==nullptr;delete p;return b;}"},
      {"callback-object", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int g(int n){return n+1;}int f(){using P=int(*)(int);P*p=new P(&g);int n=(*p)(4);delete p;return n;}"},
      {"enum-object", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};enum E{a,b};E f(){E*p=new E(b);E n=*p;delete p;return n;}"},
      {"nullptr-object", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};bool f(){using N=decltype(nullptr);N*p=new N{};bool b=*p==nullptr;delete p;return b;}"},
      {"record-aggregate", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};struct R{int n;double d;};int f(){R*p=new R{3,4};int n=p->n;delete p;return n;}"},
      {"record-array-member", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};struct R{int n[3];};int f(){R*p=new R{{3,4,5}};int n=p->n[1];delete p;return n;}"},
      {"record-construction", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};struct R{int n;R*self;R(int v):n(v),self(this){}~R(){++n;}};int f(){R*p=new R(3);int n=p->n;delete p;return n;}"},
      {"reference-field", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};struct R{int&n;};int f(){int n=3;R*p=new R{n};++p->n;delete p;return n;}"},
      {"late-global-definition", "int*f(){return new int(3);}void g(int*p){delete p;}using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};"},
      {"member-functions", "using Size=decltype(sizeof(0));struct R{int n;static void*operator new(Size){return nullptr;}static void operator delete(void*){}};R*f(){return new R{3};}void g(R*p){delete p;}"},
      {"member-sized-delete", "using Size=decltype(sizeof(0));struct R{int n;static void*operator new(Size){return nullptr;}static void operator delete(void*,Size){}};R*f(){return new R{3};}void g(R*p){delete p;}"},
      {"qualified-global", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};struct R{int n;static void*operator new(Size)=delete;static void operator delete(void*)=delete;};R*f(){return ::new R{3};}void g(R*p){::delete p;}"},
      {"class-placement", "using Size=decltype(sizeof(0));struct R{int n;static void*operator new(Size,void*p){return p;}};R*f(void*p){return new(p)R{3};}"},
      {"global-tag-placement", "using Size=decltype(sizeof(0));struct Tag{};void*operator new(Size,Tag,void*p){return p;}int*f(void*p){return ::new(Tag{},p)int(3);}"},
      {"placement-default", "using Size=decltype(sizeof(0));struct A{A(){}~A(){}};struct R{int n;static void*operator new(Size,void*p,const A&a=A()){return p;}};R*f(void*p){return new(p)R{3};}"},
      {"placement-value", "using Size=decltype(sizeof(0));struct A{int n;A(int v):n(v){}~A(){}};struct R{int n;static void*operator new(Size,void*p,A a){return p;}};R*f(void*p){return new(p,A(4))R{3};}"},
      {"null-nothrow", "using Size=decltype(sizeof(0));struct R{int n;static void*operator new(Size)noexcept{return nullptr;}R(int v):n(v){}};int effect(){return 3;}R*f(){return new R(effect());}"},
      {"free-template-placement", "using Size=decltype(sizeof(0));template<class T>void*operator new(Size,T*p){return p;}int*f(int*p){return new(p)int(3);}"},
      {"free-template-default", "using Size=decltype(sizeof(0));template<class T=int>void*operator new(Size,int*p,int n=sizeof(T)){return p;}int*f(int*p){return new(p)int(3);}"},
      {"member-template-placement", "using Size=decltype(sizeof(0));struct R{int n;template<class T>static void*operator new(Size,T*p){return p;}};R*f(void*p){return new(p)R{3};}"},
      {"class-template-placement", "using Size=decltype(sizeof(0));template<class T>struct R{T n;static void*operator new(Size,void*p){return p;}};R<int>*f(void*p){return new(p)R<int>{3};}"},
      {"class-member-template-placement", "using Size=decltype(sizeof(0));template<class T>struct R{T n;template<class P>static void*operator new(Size,P*p){return p;}};R<int>*f(void*p){return new(p)R<int>{3};}"},
      {"operator-direct-address", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};void*f(Size n){auto a=static_cast<void*(*)(Size)>(&operator new);auto d=static_cast<void(*)(void*)noexcept>(&operator delete);void*p=a(n);d(p);return p;}"},
      {"member-operator-address", "using Size=decltype(sizeof(0));struct R{static void*operator new(Size){return nullptr;}static void operator delete(void*){}};void*f(Size n){auto a=&R::operator new;auto d=&R::operator delete;void*p=a(n);d(p);return p;}"},
      {"array-operator-direct", "using Size=decltype(sizeof(0));void*operator new[](Size){return nullptr;}void operator delete[](void*)noexcept{}void*f(Size n){void*p=operator new[](n);operator delete[](p);return p;}"},
      {"explicit-reconstruction", "using Size=decltype(sizeof(0));struct Tag{};void*operator new(Size,Tag,void*p){return p;}struct R{int n;R(int v):n(v){}~R(){}};int f(){R r(3);r.~R();::new(Tag{},&r)R(4);return r.n;}"},
      {"scalar-reconstruction", "using Size=decltype(sizeof(0));struct Tag{};void*operator new(Size,Tag,void*p){return p;}int f(void*p){using I=int;I*old=new(Tag{},p)I(3);old->~I();float*value=new(Tag{},p)float(4);return static_cast<int>(*value);}"},
      {"template-new", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};template<class T>T*make(){return new T{};}int f(){int*p=make<int>();int n=*p;delete p;return n;}"},
      {"local-static-new", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int*f(){static int*p=new int(3);return p;}"},
      {"default-argument-new", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int f(int*p=new int(3)){int n=*p;delete p;return n;}int g(){return f();}"},
      {"default-member-new", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};struct R{int*p=new int(3);~R(){delete p;}};int f(){R r;return *r.p;}"},
      {"discarded-source", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};int f(){if constexpr(false){int*p=new int(3);delete p;}return 0;}"},
      {"query", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};bool f(int*p){return noexcept(new int(3))||noexcept(delete p);}"},
      {"lazy-template-body", "using Size=decltype(sizeof(0));struct R{int n;template<class T>static void*operator new(Size,T*p){T::missing();return p;}};R*f(R*p){return p;}"},
      {"protocol-source", "using Size=decltype(sizeof(0));\nunsigned char storage[64]{};\nvoid*operator new(Size n){return storage;}\nvoid operator delete(void*p)noexcept{}\nstruct R{int n;R(int v):n(v){}~R(){++n;}};\nR*make(int n){return new R(n);}\nvoid dispose(R*p){delete p;}\nint*scalar(){return new int();}\nvoid escaped(){int*p=new int(3);}\nint*late(){return new int(4);}\n"},
      {"runtime-source", "using Size=decltype(sizeof(0));\nstruct Storage{unsigned long long alignment;unsigned char bytes[128];};\nStorage slots[64]{};\nSize used=0,lastSize=0;\nint allocations=0,deallocations=0,placementCalls=0,destructions=0;\nvoid*lastFreed=nullptr;\nvoid*take(Size n){lastSize=n;++allocations;return slots[used++].bytes;}\nvoid*operator new(Size n){return take(n);}\nvoid operator delete(void*p)noexcept{lastFreed=p;++deallocations;}\nvoid operator delete(void*p,Size)noexcept{operator delete(p);}\nstruct Tag{};\nvoid*operator new(Size n,Tag,void*p){lastSize=n;++placementCalls;return p;}\nint liveArguments=0,seenArguments=0,initializers=0;\nstruct Argument{Argument(){++liveArguments;}~Argument(){--liveArguments;}};\nint initial(){++initializers;return 17;}\nstruct Failed{\n int n;\n static void*operator new(Size,const Argument&)noexcept{seenArguments=liveArguments;return nullptr;}\n Failed(int v):n(v){++initializers;}\n};\nstruct R{\n int value;R*self;R**slot;\n R(int v):value(v),self(this),slot(nullptr){}\n ~R(){++destructions;if(slot)*slot=nullptr;}\n static void*operator new(Size n){return take(n);}\n static void operator delete(void*p)noexcept{lastFreed=p;++deallocations;}\n};\nstruct Placement{\n int value;Placement*self;\n static void*operator new(Size n,void*p,const Argument&arg=Argument()){\n  lastSize=n;++placementCalls;seenArguments=liveArguments;return p;\n }\n Placement(int v):value(v),self(this){seenArguments=seenArguments*10+liveArguments;}\n ~Placement(){++destructions;}\n};\nstruct Sized{\n int value;\n static void*operator new(Size n){return take(n);}\n static void operator delete(void*p,Size n)noexcept{lastFreed=p;lastSize=n;++deallocations;}\n};\ntemplate<class T>void*operator new(Size n,T*p,int){lastSize=n;++placementCalls;return p;}\ntemplate<class T>struct Generic{\n T value;\n template<class P>static void*operator new(Size n,P*p){lastSize=n;++placementCalls;return p;}\n static void operator delete(void*p)noexcept{lastFreed=p;++deallocations;}\n};\nstruct Temporary{int*destroyed;~Temporary(){++*destroyed;}};\nstruct References{const Temporary&value;};\nint main(){\n int*p=new int(7);if(*p!=7||lastSize!=sizeof(int)||allocations!=1)return 1;\n void*expected=p;delete p;if(lastFreed!=expected||deallocations!=1)return 2;\n const int*cp=new const int(8);if(*cp!=8)return 3;expected=const_cast<int*>(cp);delete cp;if(lastFreed!=expected)return 4;\n int*z=new int();if(*z!=0)return 5;delete z;\n int*u=new int;*u=9;if(*u!=9)return 6;delete u;\n using Pointer=int*;Pointer*pp=new Pointer(nullptr);if(*pp!=nullptr)return 7;delete pp;\n using Null=decltype(nullptr);Null*np=new Null{};if(*np!=nullptr)return 8;delete np;\n Failed*failed=new(Argument{})Failed(initial());if(failed!=nullptr||initializers||liveArguments||seenArguments!=1)return 9;\n Storage storage{};seenArguments=0;\n Placement*placed=new(storage.bytes)Placement(initial());\n if(placed->self!=placed||placed->value!=17||seenArguments!=11||liveArguments||initializers!=1)return 10;\n int before=destructions;placed->~Placement();if(destructions!=before+1)return 11;\n int*first=::new(Tag{},storage.bytes)int(21);if(*first!=21)return 12;\n using I=int;first->~I();\n float*middle=::new(Tag{},storage.bytes)float(2.5f);if(*middle!=2.5f)return 13;\n using F=float;middle->~F();\n int*again=::new(Tag{},storage.bytes)int(22);if(*again!=22||again!=first)return 14;\n before=destructions;\n {R object(30);object.~R();::new(Tag{},&object)R(31);if(object.value!=31||object.self!=&object||destructions!=before+1)return 15;}\n if(destructions!=before+2)return 16;\n R*record=new R(40);expected=record;record->slot=&record;before=destructions;\n delete record;if(record!=nullptr||lastFreed!=expected||destructions!=before+1)return 17;\n before=deallocations;delete record;if(deallocations!=before)return 18;\n Sized*sized=new Sized{41};expected=sized;delete sized;if(lastFreed!=expected||lastSize!=sizeof(Sized))return 19;\n Generic<int>*generic=new(storage.bytes)Generic<int>{42};if(generic->value!=42||lastSize!=sizeof(Generic<int>))return 20;\n generic->~Generic();\n int*templated=new(storage.bytes,0)int(43);if(*templated!=43||lastSize!=sizeof(int))return 21;\n before=allocations;{int*escaped=new int(44);expected=escaped;}if(allocations!=before+1||lastFreed==expected)return 22;\n delete static_cast<int*>(expected);if(lastFreed!=expected)return 23;\n R*escapedRecord=nullptr;before=destructions;\n {R*local=new R(45);escapedRecord=local;}if(destructions!=before)return 24;\n delete escapedRecord;if(destructions!=before+1)return 25;\n int temporaryDestructions=0;References*references=new References{Temporary{&temporaryDestructions}};\n if(temporaryDestructions!=1)return 26;delete references;if(temporaryDestructions!=1)return 27;\n return 0;\n}\n"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    auto Source = tmpFile("allocation-" + Name + ".cpp");
    auto Output = tmpFile("allocation-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

TEST_F(TranslateTest, CoreV2AllocationRetainsSourceAndRuntimeBoundaries) {
  const std::vector<std::tuple<std::string, std::string, std::string>> Cases = {
      {"written-new-visibility-default", "using Size=decltype(sizeof(0));__attribute__((visibility(\"default\"))) void*operator new(Size){return nullptr;}", "TR0201"},
      {"written-delete-visibility-default", "__attribute__((visibility(\"default\"))) void operator delete(void*)noexcept{}", "TR0201"},
      {"written-array-visibility-default", "using Size=decltype(sizeof(0));__attribute__((visibility(\"default\"))) void*operator new[](Size){return nullptr;}", "TR0201"},
      {"written-visibility-inherited", "using Size=decltype(sizeof(0));__attribute__((visibility(\"default\"))) void*operator new(Size);void*operator new(Size){return nullptr;}", "TR0201"},
      {"discarded-void-new", "void f(){static_cast<void>(new int(1));}", "TR0203"},
      {"discarded-new", "int f(){if constexpr(false){int*p=new int(3);}return 0;}", "TR0203"},
      {"template-new", "template<class T>T* f(){return new T{};}int main(){return *f<int>();}", "TR0203"},
      {"default-argument-new", "int f(int*p=new int(1)){return *p;}", "TR0203"},
      {"void-new", "void*f(){return new void;}", "TR0202"},
      {"default-member-new", "struct R{int*p=new int(1);};", "TR0203"},
      {"record-new", "struct R{int n;~R(){}};R*f(){return new R{1};}", "TR0203"},
      {"record-delete", "struct R{int n;~R(){}};void f(R*p){delete p;}", "TR0203"},
      {"missing-class-new", "using Size=decltype(sizeof(0));struct R{int n;static void*operator new(Size);};R*f(){return new R{3};}", "TR0203"},
      {"missing-class-delete", "struct R{int n;static void operator delete(void*);};void f(R*p){delete p;}", "TR0203"},
      {"missing-placement", "using Size=decltype(sizeof(0));void*operator new(Size,void*);int*f(void*p){return new(p)int(3);}", "TR0203"},
      {"reserved-placement-definition", "using Size=decltype(sizeof(0));void*operator new(Size,void*p){return p;}", "TR0203"},
      {"reserved-placement-delete", "void operator delete(void*,void*){}", "TR0203"},
      {"array-new", "int*f(){return new int[3]{};}", "TR0203"},
      {"array-delete", "void f(int*p){delete[]p;}", "TR0203"},
      {"alias-array-new", "using A=int[3];int*f(){return new A{};}", "TR0203"},
      {"incomplete-new", "struct R;R*f(){return new R;}", "TR0202"},
      {"void-delete", "void f(void*p){delete p;}", "TR0201"},
      {"incomplete-delete", "struct R;void f(R*p){delete p;}", "TR0201"},
      {"written-attribute", "using Size=decltype(sizeof(0));__attribute__((returns_nonnull))void*operator new(Size){return nullptr;}", "TR0201"},
      {"allocator-body", "using Size=decltype(sizeof(0));void*operator new(Size){long double n=0;return nullptr;}", "TR0201"},
      {"placement-source-erasure", "using Size=decltype(sizeof(0));struct Tag{};void*operator new(Size,Tag,void*p){return p;}int*f(void*p){return new(Tag{},(sizeof(long double),p))int(3);}", "TR0201"},
      {"allocated-written-type", "using Size=decltype(sizeof(0));struct Tag{};void*operator new(Size,Tag,void*p){return p;}int*f(void*p){return new(Tag{},p)decltype(sizeof(long double),int())(3);}", "TR0201"},
      {"template-default-source", "using Size=decltype(sizeof(0));template<class T=long double>void*operator new(Size,int*p){return p;}int*f(int*p){return new(p)int(3);}", "TR0201"},
      {"selected-template-body", "using Size=decltype(sizeof(0));template<class T>void*operator new(Size,T*p){T::missing();return p;}int*f(int*p){return new(p)int(3);}", "TR0202"},
      {"constructor-body", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};struct R{R(){long double n=0;}};R*f(){return new R;}", "TR0201"},
      {"destructor-body", "using Size=decltype(sizeof(0));struct Storage{unsigned long long alignment;unsigned char bytes[128];};Storage storage{};void*operator new(Size){return storage.bytes;}void operator delete(void*)noexcept{};struct R{~R(){long double n=0;}};void f(R*p){delete p;}", "TR0201"},
      {"invalid-size-parameter", "void*operator new(int){return nullptr;}", "TR0202"},
      {"invalid-return-type", "using Size=decltype(sizeof(0));int*operator new(Size){return nullptr;}", "TR0202"},
  };
  for (const auto &[Name, Code, Diagnostic] : Cases) {
    SCOPED_TRACE(Name);
    auto Source = tmpFile("allocation-reject-" + Name + ".cpp");
    auto Output = tmpFile("allocation-reject-" + Name + ".nc");
    writeFile(Source, Code);
    expectCode(translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()}), Diagnostic);
    expectNoArtifacts(Output);
  }
  for (const auto &Code : {"int*f(){return new int(3);}", "void f(int*p){delete p;}"}) {
    auto Source = tmpFile("allocation-v1.cpp");
    auto Output = tmpFile("allocation-v1.nc");
    writeFile(Source, Code);
    expectCode(translate(Source, {"-o", Output.string()}), "TR0201");
    expectNoArtifacts(Output);
  }
}

TEST_F(TranslateTest, CoreV2AllocationPreservesStorageIdentityAndLifetimes) {
  auto Source = tmpFile("allocation-runtime.cpp");
  auto Output = tmpFile("allocation-runtime.nc");
  writeFile(Source, R"cpp(using Size=decltype(sizeof(0));
struct Storage{unsigned long long alignment;unsigned char bytes[128];};
Storage slots[64]{};
Size used=0,lastSize=0;
int allocations=0,deallocations=0,placementCalls=0,destructions=0;
void*lastFreed=nullptr;
void*take(Size n){lastSize=n;++allocations;return slots[used++].bytes;}
void*operator new(Size n){return take(n);}
void operator delete(void*p)noexcept{lastFreed=p;++deallocations;}
void operator delete(void*p,Size)noexcept{operator delete(p);}
struct Tag{};
void*operator new(Size n,Tag,void*p){lastSize=n;++placementCalls;return p;}
int liveArguments=0,seenArguments=0,initializers=0;
struct Argument{Argument(){++liveArguments;}~Argument(){--liveArguments;}};
int initial(){++initializers;return 17;}
struct Failed{
 int n;
 static void*operator new(Size,const Argument&)noexcept{seenArguments=liveArguments;return nullptr;}
 Failed(int v):n(v){++initializers;}
};
struct R{
 int value;R*self;R**slot;
 R(int v):value(v),self(this),slot(nullptr){}
 ~R(){++destructions;if(slot)*slot=nullptr;}
 static void*operator new(Size n){return take(n);}
 static void operator delete(void*p)noexcept{lastFreed=p;++deallocations;}
};
struct Placement{
 int value;Placement*self;
 static void*operator new(Size n,void*p,const Argument&arg=Argument()){
  lastSize=n;++placementCalls;seenArguments=liveArguments;return p;
 }
 Placement(int v):value(v),self(this){seenArguments=seenArguments*10+liveArguments;}
 ~Placement(){++destructions;}
};
struct Sized{
 int value;
 static void*operator new(Size n){return take(n);}
 static void operator delete(void*p,Size n)noexcept{lastFreed=p;lastSize=n;++deallocations;}
};
template<class T>void*operator new(Size n,T*p,int){lastSize=n;++placementCalls;return p;}
template<class T>struct Generic{
 T value;
 template<class P>static void*operator new(Size n,P*p){lastSize=n;++placementCalls;return p;}
 static void operator delete(void*p)noexcept{lastFreed=p;++deallocations;}
};
struct Temporary{int*destroyed;~Temporary(){++*destroyed;}};
struct References{const Temporary&value;};
int main(){
 int*p=new int(7);if(*p!=7||lastSize!=sizeof(int)||allocations!=1)return 1;
 void*expected=p;delete p;if(lastFreed!=expected||deallocations!=1)return 2;
 const int*cp=new const int(8);if(*cp!=8)return 3;expected=const_cast<int*>(cp);delete cp;if(lastFreed!=expected)return 4;
 int*z=new int();if(*z!=0)return 5;delete z;
 int*u=new int;*u=9;if(*u!=9)return 6;delete u;
 using Pointer=int*;Pointer*pp=new Pointer(nullptr);if(*pp!=nullptr)return 7;delete pp;
 using Null=decltype(nullptr);Null*np=new Null{};if(*np!=nullptr)return 8;delete np;
 Failed*failed=new(Argument{})Failed(initial());if(failed!=nullptr||initializers||liveArguments||seenArguments!=1)return 9;
 Storage storage{};seenArguments=0;
 Placement*placed=new(storage.bytes)Placement(initial());
 if(placed->self!=placed||placed->value!=17||seenArguments!=11||liveArguments||initializers!=1)return 10;
 int before=destructions;placed->~Placement();if(destructions!=before+1)return 11;
 int*first=::new(Tag{},storage.bytes)int(21);if(*first!=21)return 12;
 using I=int;first->~I();
 float*middle=::new(Tag{},storage.bytes)float(2.5f);if(*middle!=2.5f)return 13;
 using F=float;middle->~F();
 int*again=::new(Tag{},storage.bytes)int(22);if(*again!=22||again!=first)return 14;
 before=destructions;
 {R object(30);object.~R();::new(Tag{},&object)R(31);if(object.value!=31||object.self!=&object||destructions!=before+1)return 15;}
 if(destructions!=before+2)return 16;
 R*record=new R(40);expected=record;record->slot=&record;before=destructions;
 delete record;if(record!=nullptr||lastFreed!=expected||destructions!=before+1)return 17;
 before=deallocations;delete record;if(deallocations!=before)return 18;
 Sized*sized=new Sized{41};expected=sized;delete sized;if(lastFreed!=expected||lastSize!=sizeof(Sized))return 19;
 Generic<int>*generic=new(storage.bytes)Generic<int>{42};if(generic->value!=42||lastSize!=sizeof(Generic<int>))return 20;
 generic->~Generic();
 int*templated=new(storage.bytes,0)int(43);if(*templated!=43||lastSize!=sizeof(int))return 21;
 before=allocations;{int*escaped=new int(44);expected=escaped;}if(allocations!=before+1||lastFreed==expected)return 22;
 delete static_cast<int*>(expected);if(lastFreed!=expected)return 23;
 R*escapedRecord=nullptr;before=destructions;
 {R*local=new R(45);escapedRecord=local;}if(destructions!=before)return 24;
 delete escapedRecord;if(destructions!=before+1)return 25;
 int temporaryDestructions=0;References*references=new References{Temporary{&temporaryDestructions}};
 if(temporaryDestructions!=1)return 26;delete references;if(temporaryDestructions!=1)return 27;
 return 0;
}
)cpp");
  auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const auto &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    auto Executable = tmpFile(std::string("allocation-runtime") + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization,
                                     {"-fno-inline", "-fstrict-aliasing"});
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2ExplicitDestructionAcceptsSourceLifetimes) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"class-defaulted", "template<class T>struct R{~R()=default;};void f(R<int>&r){r.~R();}"},
      {"class-body", "template<class T>struct R{~R(){}};void f(R<int>&r){r.~R();}"},
      {"class-dead", "template<class T>struct R{~R(){}};void f(R<int>&r){if(false)r.~R();}"},
      {"query", "struct R{int n;~R()noexcept{}};bool f(R&r){return noexcept(r.~R());}"},
      {"defaulted-local", "struct R{int n;~R()=default;};void f(){R r{1};r.~R();}"},
      {"record-body", "struct R{int n;~R(){}};void f(R&r){r.~R();}"},
      {"record-dead", "struct R{int n;~R(){}};void f(R&r){if(false)r.~R();}"},
      {"record-alias", "struct R{int n;~R(){}};using T=R;void f(R&r){r.~T();}"},
      {"arrow", "struct R{int n;~R(){++n;}};void f(R*p){p->~R();}"},
      {"const", "struct R{int*p;~R(){++*p;}};void f(const R&r){r.~R();}"},
      {"qualified", "namespace N{struct R{int n;~R(){}};}void f(N::R*p){p->N::R::~R();}"},
      {"outside", "struct R{int n;~R();};R::~R(){++n;}void f(R*p){p->~R();}"},
      {"implicit-trivial", "struct R{int n;};void f(R*p){p->~R();}"},
      {"implicit-members", "struct I{int n;~I(){++n;}};struct R{I values[2];};void f(R*p){p->~R();}"},
      {"defaulted-members", "struct I{int n;~I(){++n;}};struct R{I values[2];~R()=default;};void f(R*p){p->~R();}"},
      {"receiver-effects", "struct R{int n;~R(){++n;}};R*next(R*p,int&n){++n;return p;}void f(R*p,int&n){next(p,n)->~R();}"},
      {"conditional-receiver", "struct R{int n;~R(){++n;}};void f(bool b,R&a,R&c){(b?a:c).~R();}"},
      {"template-record", "template<class T>void destroy(T*p){p->~T();}struct R{int n;~R(){++n;}};void f(R*p){destroy(p);}"},
      {"template-scalar", "template<class T>void destroy(T*p){p->~T();}void f(int*p){destroy(p);}"},
      {"template-qualified-scalar", "template<class T>void destroy(T*p){p->T::~T();}void f(int*p){destroy(p);}"},
      {"dependent-record-alias", "template<class T>struct R{using Self=R;int n;~R(){++n;}void destroy(){this->~Self();}};void f(R<int>*p){p->destroy();}"},
      {"template-outside", "template<class T>struct R{T n;~R();};template<class T>R<T>::~R(){++n;}void f(R<int>*p){p->~R();}"},
      {"query-declared-template", "template<class T>struct R{T n;~R()noexcept;};bool f(R<int>&r){return noexcept(r.~R());}"},
      {"query-lazy-body", "template<class T>struct R{T n;~R()noexcept{T::missing();}};bool f(R<int>&r){return noexcept(r.~R());}"},
      {"query-sizeof", "struct R{int n;~R(){++n;}};unsigned long long f(R&r){return sizeof((r.~R(),1));}"},
      {"scalar-uninitialized", "using I=int;void f(){I n;n.~I();}"},
      {"scalar-arrow", "using I=int;void f(I*p){p->~I();}"},
      {"scalar-qualified", "using I=int;void f(I*p){p->I::~I();}"},
      {"scalar-const", "using I=int;void f(const I&v){v.~I();}"},
      {"scalar-float", "using F=float;void f(F&v){v.~F();}"},
      {"scalar-enum", "enum E{a,b};void f(E&v){v.~E();}"},
      {"scalar-pointer", "using P=int*;void f(){P p;p.~P();}"},
      {"scalar-callback", "using F=int(*)(int);void f(){F p;p.~F();}"},
      {"scalar-nullptr", "using N=decltype(nullptr);void f(){N p;p.~N();}"},
      {"scalar-comma", "using I=int;void f(I&v,int&calls){(++calls,v).~I();}"},
      {"scalar-index", "using I=int;void f(I*p,int&i){p[i++].~I();}"},
      {"scalar-temporary-base", "using I=int;struct R{I n;~R(){}};void f(){R{1}.n.~I();}"},
      {"protocol-source", "int effects=0;\nint calls=0;\nstruct Leaf{int tag;~Leaf(){effects=effects*10+tag;}};\nstruct Box{Leaf items[2];~Box(){effects+=3;}};\nvoid destroy(Box*p){p->~Box();}\nvoid destroyConst(const Box&p){p.~Box();}\nvoid keepAutomatic(){Box box{{{1},{2}}};if(false)box.~Box();}\nusing I=int;\nI*next(I*p){++calls;return p;}\nvoid pseudo(I*p){next(p)->~I();}\nvoid uninitialized(){I value;value.~I();}\nbool query(Box&p){return noexcept(p.~Box());}\n"},
      {"runtime-source", "int calls=0;\nint constructions=0;\nusing I=int;\nusing P=int*;\nusing F=int(*)(int);\nusing N=decltype(nullptr);\nI*next(I*p){++calls;return p;}\nI*nextQuiet(I*p)noexcept{++calls;return p;}\ntemplate<class T>constexpr bool dependentQuiet(T*p){return noexcept(next(p)->~T());}\nstruct R{int n;R(int value):n(value){++constructions;}~R()=default;};\nR*nextRecord(R*p){++calls;return p;}\ntemplate<class T>void destroy(T*p){p->T::~T();}\nstruct Counter{~Counter(){++calls;}};\nint main(){\n I value;value.~I();if(calls)return 1;\n I second;next(&second)->~I();if(calls!=1)return 2;\n I third;destroy(&third);if(calls!=1)return 3;\n I array[2];int index=0;array[index++].~I();if(index!=1)return 4;\n I fourth;(++calls,fourth).~I();if(calls!=2)return 5;\n P pointer;pointer.~P();F callback;callback.~F();N nullValue;nullValue.~N();\n {R record(3);nextRecord(&record)->~R();}if(calls!=3||constructions!=1)return 6;\n {const R record(4);record.~R();}if(constructions!=2)return 7;\n {R record(5);destroy(&record);}if(constructions!=3)return 8;\n {Counter counter;if(false)counter.~Counter();}if(calls!=4)return 9;\n I fifth;bool quiet=noexcept(next(&fifth)->~I());if(quiet||calls!=4)return 10;\n if(!noexcept(fifth.~I())||!noexcept(nextQuiet(&fifth)->~I())||dependentQuiet(&fifth)||calls!=4)return 11;\n return 0;\n}\n"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    auto Source = tmpFile("explicit-destruction-" + Name + ".cpp");
    auto Output = tmpFile("explicit-destruction-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
    EXPECT_NE(readFile(Output).find("__has_attribute(may_alias)"), std::string::npos);
  }
}

TEST_F(TranslateTest, CoreV2ExplicitDestructionRetainsSourceBoundaries) {
  const std::vector<std::tuple<std::string, std::string, std::string>> Cases = {
      {"virtual", "struct R{virtual ~R(){}};void f(R*p){p->~R();}", "TR0201"},
      {"deleted", "struct R{~R()=delete;};void f(R*p){p->~R();}", "TR0202"},
      {"private", "class R{~R(){}};void f(R*p){p->~R();}", "TR0202"},
      {"missing", "struct R{int n;~R();};void f(R*p){p->~R();}", "TR0203"},
      {"missing-template", "template<class T>struct R{T n;~R();};void f(R<int>*p){p->~R();}", "TR0203"},
      {"body-source", "struct R{int n;~R(){long double bad=1;}};void f(R*p){p->~R();}", "TR0201"},
      {"spec-source", "template<class T>struct R{T n;~R()noexcept(sizeof(long double)>0);};bool f(R<int>&r){return noexcept(r.~R());}", "TR0201"},
      {"scalar-type", "using T=long double;void f(T&p){p.~T();}", "TR0201"},
      {"scalar-source-erasure", "using I=int;void f(I&n){(sizeof(long double),n).~I();}", "TR0201"},
      {"scalar-volatile", "using I=int;void f(volatile I&n){n.~I();}", "TR0201"},
      {"scalar-wrong-type", "using I=int;using F=float;void f(I&p){p.~F();}", "TR0202"},
      {"scalar-argument", "using I=int;void f(I&p){p.~I(1);}", "TR0202"},
      {"runtime-template-body", "template<class T>struct R{T n;~R(){T::missing();}};void f(R<int>&r){r.~R();}", "TR0202"},
  };
  for (const auto &[Name, Code, Diagnostic] : Cases) {
    SCOPED_TRACE(Name);
    auto Source = tmpFile("explicit-destruction-reject-" + Name + ".cpp");
    auto Output = tmpFile("explicit-destruction-reject-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    expectCode(Result, Diagnostic);
    expectNoArtifacts(Output);
  }
  for (const auto &Code : {"using I=int;void f(I&n){n.~I();}",
                           "struct R{int n;};void f(R&r){r.~R();}"}) {
    auto Source = tmpFile("explicit-destruction-v1.cpp");
    auto Output = tmpFile("explicit-destruction-v1.nc");
    writeFile(Source, Code);
    expectCode(translate(Source, {"-o", Output.string()}), "TR0201");
    expectNoArtifacts(Output);
  }
}

TEST_F(TranslateTest, CoreV2ExplicitDestructionPreservesReceiverEffectsAndCleanup) {
  auto Source = tmpFile("explicit-destruction-runtime.cpp");
  auto Output = tmpFile("explicit-destruction-runtime.nc");
  writeFile(Source, R"cpp(int calls=0;
int constructions=0;
using I=int;
using P=int*;
using F=int(*)(int);
using N=decltype(nullptr);
I*next(I*p){++calls;return p;}
I*nextQuiet(I*p)noexcept{++calls;return p;}
template<class T>constexpr bool dependentQuiet(T*p){return noexcept(next(p)->~T());}
struct R{int n;R(int value):n(value){++constructions;}~R()=default;};
R*nextRecord(R*p){++calls;return p;}
template<class T>void destroy(T*p){p->T::~T();}
struct Counter{~Counter(){++calls;}};
int main(){
 I value;value.~I();if(calls)return 1;
 I second;next(&second)->~I();if(calls!=1)return 2;
 I third;destroy(&third);if(calls!=1)return 3;
 I array[2];int index=0;array[index++].~I();if(index!=1)return 4;
 I fourth;(++calls,fourth).~I();if(calls!=2)return 5;
 P pointer;pointer.~P();F callback;callback.~F();N nullValue;nullValue.~N();
 {R record(3);nextRecord(&record)->~R();}if(calls!=3||constructions!=1)return 6;
 {const R record(4);record.~R();}if(constructions!=2)return 7;
 {R record(5);destroy(&record);}if(constructions!=3)return 8;
 {Counter counter;if(false)counter.~Counter();}if(calls!=4)return 9;
 I fifth;bool quiet=noexcept(next(&fifth)->~I());if(quiet||calls!=4)return 10;
 if(!noexcept(fifth.~I())||!noexcept(nextQuiet(&fifth)->~I())||dependentQuiet(&fifth)||calls!=4)return 11;
 return 0;
}
)cpp");
  auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const auto &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    auto Executable = tmpFile(std::string("explicit-destruction-runtime") + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization,
                                     {"-fno-inline", "-fstrict-aliasing"});
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

