TEST_F(TranslateTest, CoreV2FrontendRepairsPreserveImportsAndExceptionQueries) {
  const auto Source = tmpFile("frontend-repairs.cpp");
  const auto Output = tmpFile("frontend-repairs.nc");
  writeFile(Source, R"cpp(namespace Original{int count=3;using Value=int;int read(int v){return v;}}
namespace First{using Original::count;using Original::Value;using Original::read;}
namespace Second{using First::count;using First::Value;using First::read;}
template<class T>int query(T v)noexcept(sizeof(T)==sizeof(int)){return v;}
template<int N>int valueQuery()noexcept(N>0){return N;}
template<class T>int (parenthesized)(T v)noexcept(sizeof(T)==sizeof(int)){return v;}
template<class T,int N>struct Box{T n;Box(T v)noexcept(N>0):n(v){}T get()const noexcept(sizeof(T)==sizeof(int)){return n;}};
template<class T>struct Later{T n;Later(T v)noexcept(sizeof(T)==sizeof(int));T get()const noexcept(sizeof(T)==sizeof(int));};
template<class T>Later<T>::Later(T v)noexcept(sizeof(T)==sizeof(int)):n(v){}
template<class T>T Later<T>::get()const noexcept(sizeof(T)==sizeof(int)){return n;}
int callInt(int v){return query(v);}
int callBool(bool v){return query(v);}
int callThree(){return valueQuery<3>();}
int callZero(){return valueQuery<0>();}
int callParens(int v){return parenthesized(v);}
int callBox(int v){Box<int,3>b(v);return b.get();}
int callFalseBox(int v){Box<int,0>b(v);return b.get();}
int callLater(int v){Later<int>b(v);return b.get();}
bool intFlag(){return noexcept(query(1));}
bool boolFlag(){return noexcept(query(true));}
bool threeFlag(){return noexcept(valueQuery<3>());}
bool zeroFlag(){return noexcept(valueQuery<0>());}
bool ctorFlag(){return noexcept(Box<int,3>(1));}
bool falseCtorFlag(){return noexcept(Box<int,0>(1));}
int imports(){using Second::Value;using Second::read;Value n=Second::count;return read(n);}
int main(){
 if(callInt(3)!=3||callBool(true)!=1)return 1;
 if(!intFlag()||boolFlag())return 2;
 if(callThree()!=3||callZero()!=0||!threeFlag()||zeroFlag())return 3;
 if(callParens(4)!=4)return 4;
 if(callBox(5)!=5||callFalseBox(6)!=6||!ctorFlag()||falseCtorFlag())return 5;
 if(callLater(7)!=7)return 6;
 if(imports()!=3)return 7;
 return 0;
}
)cpp");
  auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("frontend-repairs" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization, {"-fno-inline"});
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2FrontendRepairsAcceptSourceOwnedConcreteFunctions) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"shadow-reexports", "namespace N{int n=3;using T=int;int f(int v){return v;}}namespace A{using N::n;using N::T;using N::f;}namespace B{using A::n;using A::T;using A::f;}int main(){using B::T;using B::f;T v=B::n;return f(v)-3;}"},
      {"noexcept-resolved", "template<class T>int f(T v)noexcept(sizeof(T)==sizeof(int)){return v;}int main(){return f(3)-3;}"},
      {"noexcept-false", "template<class T>int f(T v)noexcept(sizeof(T)!=sizeof(int)){return v;}int main(){return f(3)-3+noexcept(f(3));}"},
      {"noexcept-parens", "template<class T>int (f)(T v)noexcept(sizeof(T)==sizeof(int)){return v;}int main(){return f(3)-3;}"},
      {"noexcept-value", "template<int N>int f()noexcept(N>0){return N;}int main(){return f<3>()-3+f<0>();}"},
      {"noexcept-method", "template<class T>struct R{T n;T get()const noexcept(sizeof(T)==sizeof(int)){return n;}};int main(){R<int>r{3};return r.get()-3;}"},
      {"noexcept-method-value", "template<int N>struct R{int get()const noexcept(N>0){return N;}};int main(){R<3>a;R<0>b;return a.get()-3+b.get();}"},
      {"noexcept-constructor", "template<class T>struct R{T n;R(T v)noexcept(sizeof(T)==sizeof(int)):n(v){}};int main(){R<int>r(3);return r.n-3;}"},
      {"noexcept-constructor-value", "template<int N>struct R{int n;R()noexcept(N>0):n(N){}};int main(){R<3>a;R<0>b;return a.n-3+b.n;}"},
      {"noexcept-out-of-line", "template<class T>struct R{T n;R(T v)noexcept(sizeof(T)==sizeof(int));T get()const noexcept(sizeof(T)==sizeof(int));};template<class T>R<T>::R(T v)noexcept(sizeof(T)==sizeof(int)):n(v){}template<class T>T R<T>::get()const noexcept(sizeof(T)==sizeof(int)){return n;}int main(){R<int>r(3);return r.get()-3;}"},
      {"noexcept-explicit-specialization", "template<class T>int f(T v)noexcept(sizeof(T)==sizeof(int)){return v;}template<>int f<int>(int v)noexcept(true){return v+1;}int main(){return f(3)-4;}"},
      {"noexcept-local-method", "template<class T>int f(T v)noexcept(sizeof(T)==sizeof(int)){struct R{int get()const noexcept(sizeof(int)==4){return 3;}};R r;return r.get()+v;}int main(){return f(3)-6;}"},
      {"noexcept-written-decltype", "template<class T>auto f(decltype(static_cast<T>(1)) v)noexcept(sizeof(T)==sizeof(int))->decltype(static_cast<T>(1)){return v;}int main(){return f<int>(3)-3;}"},
      {"consteval-local", "int main(){int consteval=3;return consteval-3;}"},
      {"consteval-function", "int consteval(int n){return n;}int main(){return consteval(3)-3;}"},
      {"consteval-template", "template<class T>int f(T consteval){if constexpr(sizeof(T)==sizeof(int))return consteval;else return 0;}int main(){return f(3)-3;}"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("frontend-repairs-positive-" + Name + ".cpp");
    const auto Output = tmpFile("frontend-repairs-positive-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    EXPECT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

TEST_F(TranslateTest, CoreV2FrontendRepairsRetainWrittenExceptionSource) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"noexcept-selected-floating", "template<class T>int f(T v)noexcept(sizeof(T)==sizeof(int)&&1.0L>0.0L){return v;}int main(){return f(3);}"},
      {"noexcept-method-floating", "template<class T>struct R{int get()const noexcept(sizeof(T)==sizeof(int)&&1.0L>0.0L){return 3;}};int main(){R<int>r;return r.get();}"},
      {"noexcept-constructor-floating", "template<class T>struct R{int n;R()noexcept(sizeof(T)==sizeof(int)&&1.0L>0.0L):n(3){}};int main(){R<int>r;return r.n;}"},
      {"noexcept-return-source", "template<class T>auto f(T v)noexcept(sizeof(T)==sizeof(int))->decltype(static_cast<T>(1.0L)){return v;}int main(){return f(3);}"},
      {"noexcept-parameter-source", "template<class T>int f(decltype(static_cast<T>(1.0L)) v)noexcept(sizeof(T)==sizeof(int)){return v;}int main(){return f<int>(3);}"},
      {"noexcept-redeclaration-source", "template<class T>int f(T v)noexcept(true);template<class T>int f(T v)noexcept(1.0L>0.0L){return v;}int main(){return f(3);}"},
      {"noexcept-ordinary-source", "int f(int v)noexcept(1.0L>0.0L){return v;}int main(){return f(3);}"},
      {"noexcept-local-method-source", "template<class T>int f(T v)noexcept(sizeof(T)==sizeof(int)){struct R{int get()const noexcept(1.0L>0.0L){return 3;}};R r;return r.get()+v;}int main(){return f(3);}"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("frontend-repairs-reject-" + Name + ".cpp");
    const auto Output = tmpFile("frontend-repairs-reject-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    expectCode(Result, "TR0201");
    expectNoArtifacts(Output);
  }
}

TEST_F(TranslateTest, CoreV2FreshReferenceArgumentsPreserveConversionsAndLifetime) {
  const auto Source = tmpFile("fresh-reference-runtime.cpp");
  const auto Output = tmpFile("fresh-reference-runtime.nc");
  writeFile(Source, R"cpp(int calls=0;
template<class T>struct Mutable{T n;operator decltype(auto)(){++calls;return (n);}};
template<class T>struct Constant{T n;operator decltype(auto)()const{++calls;return (n);}};
template<class T>struct Collapse{T n;operator auto&&(){++calls;return (n);}};
template<class T>struct Move{T n;operator decltype(auto)(){++calls;return static_cast<T&&>(n);}};
template<class T>struct Value{T n;operator auto(){++calls;return n;}};
template<class T>struct Competing{T n;operator int&&(){++calls;return static_cast<int&&>(n);}operator auto&(){++calls;return n;}};
template<class T>struct Widen{T n;operator auto&(){++calls;return n;}};
int&set(int&n){n=7;return n;}
const int&get(const int&n){return n;}
int&&take(int&&n){n=9;return static_cast<int&&>(n);}
int choose(int&n){n=11;return 1;}
int choose(const int&n){return 2;}
int read(const int&n){return n;}
long long widen(const long long&n){return n+3;}
int live=0;
struct Life{int n;Life(int v):n(v){++live;}~Life(){--live;}};
template<class T>Life operator+(const Life&r,T n){return Life(r.n+n);}
int observe(const Life&r){return r.n+10*live;}
int consume(Life r){return r.n+10*live;}
int main(){
 Mutable<int>a{1};int&x=set(a);
 if(a.n!=7||&x!=&a.n||calls!=1)return 1;
 const Constant<int>b{2};const int&y=get(b);
 if(y!=2||&y!=&b.n||calls!=2)return 2;
 Collapse<int>c{3};int&z=set(c);
 if(c.n!=7||&z!=&c.n||calls!=3)return 3;
 Move<int>d{4};int&&w=take(d);
 if(d.n!=9||&w!=&d.n||calls!=4)return 4;
 struct Overload{int n;operator decltype(auto)(){++calls;return (n);}};
 Overload e{5};int selected=choose(e);
 if(selected!=1||e.n!=11||calls!=5)return 5;
 Value<int>f{6};int value=read(f);
 if(value!=6||f.n!=6||calls!=6)return 6;
 Competing<int>g{7};int&&chosenReference=take(g);
 if(g.n!=9||&chosenReference!=&g.n||calls!=7)return 7;
 {
  Life original(2);
  bool inside=observe(original+3)==25&&live==2;
  if(!inside||live!=1)return 8;
  int viewed=observe(original+4);
  if(viewed!=26||live!=1)return 9;
  int consumed=consume(original+5);
  if(consumed!=27||live!=1)return 10;
 }
 if(live!=0)return 11;
 Widen<int>h{6};long long widened=widen(h);
 if(widened!=9||h.n!=6||calls!=8)return 12;
 return 0;
}
)cpp");
  auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("fresh-reference-runtime" + Optimization);
    auto Build = compileGenerated(Output, Executable, Optimization, {"-fno-inline"});
    ASSERT_EQ(Build.exitCode, 0) << Build.out << Build.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2FreshReferenceArgumentsPositive) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"ordinary-argument", "struct R{int n;operator decltype(auto)(){return (n);}};void set(int&n){n=7;}void f(R&r){set(r);}"},
      {"const-argument", "template<class T>struct R{T n;operator decltype(auto)()const{return (n);}};int get(const int&n){return n;}int f(const R<int>&r){return get(r);}"},
      {"collapsed-argument", "template<class T>struct R{T n;operator auto&&(){return (n);}};void set(int&n){n=7;}void f(R<int>&r){set(r);}"},
      {"auto-lvalue-argument", "template<class T>struct R{T n;operator auto&(){return n;}};void set(int&n){n=7;}void f(R<int>&r){set(r);}"},
      {"rvalue-argument", "template<class T>struct R{T n;operator decltype(auto)(){return static_cast<T&&>(n);}};void set(int&&n){n=7;}void f(R<int>&r){set(r);}"},
      {"auto-rvalue-argument", "template<class T>struct R{T n;operator auto&&(){return static_cast<T&&>(n);}};void set(int&&n){n=7;}void f(R<int>&r){set(r);}"},
      {"const-rvalue-argument", "template<class T>struct R{T n;operator auto&&()const{return static_cast<const T&&>(n);}};int get(const int&&n){return n;}int f(const R<int>&r){return get(r);}"},
      {"value-const-argument", "template<class T>struct R{T n;operator auto(){return n;}};int get(const int&n){return n;}int f(R<int>&r){return get(r);}"},
      {"overload-argument", "template<class T>struct R{T n;operator decltype(auto)(){return (n);}};int choose(int&){return 1;}int choose(const int&){return 2;}int f(R<int>&r){return choose(r);}"},
      {"outside-argument", "template<class T>struct R{T n;operator decltype(auto)();};template<class T>R<T>::operator decltype(auto)(){return (n);}void set(int&n){n=7;}void f(R<int>&r){set(r);}"},
      {"irrelevant-value", "template<class T>struct R{int n;operator int&(){return n;}operator auto(){return T::missing;}};void set(int&n){n=7;}void f(R<int>&r){set(r);}"},
      {"irrelevant-pointer", "template<class T>struct R{int n;operator int&(){return n;}operator auto*(){return T::missing;}};void set(int&n){n=7;}void f(R<int>&r){set(r);}"},
      {"irrelevant-const-rvalue", "template<class T>struct R{int n;operator int&(){return n;}operator const auto&&(){return T::missing;}};void set(int&n){n=7;}void f(R<int>&r){set(r);}"},
      {"irrelevant-pointer-rvalue", "template<class T>struct R{int n;operator int&(){return n;}operator auto*&&(){return T::missing;}};void set(int&n){n=7;}void f(R<int>&r){set(r);}"},
      {"valid-competing-lvalue-for-rvalue", "template<class T>struct R{int n;operator int&&(){return static_cast<int&&>(n);}operator auto&(){return n;}};void set(int&&n){n=7;}void f(R<int>&r){set(r);}"},
      {"indirect-lvalue-to-const-reference", "template<class T>struct R{T n;operator auto&(){return n;}};long long set(const long long&n){return n;}long long f(R<int>&r){return set(r);}"},
      {"promoted-value-default", "struct R{int n;};template<int N=3>int operator+(R,R){return N;}"},
      {"selected-value-default", "struct R{int n;};template<int N=3>int operator+(R,R){return N;}int f(){R r{1};return r+r;}"},
      {"protocol-source", "template<class T>struct RefArg{\n T n;operator decltype(auto)(){return (n);}\n};\ntemplate<class T>struct ConstArg{\n T n;operator decltype(auto)()const{return (n);}\n};\ntemplate<class T>struct MoveArg{\n T n;operator auto&&(){return static_cast<T&&>(n);}\n};\nint&assignArgument(int&n){n=7;return n;}\nconst int&readArgument(const int&n){return n;}\nint&&moveArgument(int&&n){n=9;return static_cast<int&&>(n);}\nint&freshMutable(RefArg<int>&r){return assignArgument(r);}\nconst int&freshConst(const ConstArg<int>&r){return readArgument(r);}\nint&&freshRvalue(MoveArg<int>&r){return moveArgument(r);}\n"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("fresh-reference-positive-" + Name + ".cpp");
    const auto Output = tmpFile("fresh-reference-positive-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    EXPECT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

