template<class T>struct Copy{T n;Copy(T v):n(v){++live;}Copy(const Copy&r):n(r.n){++copies;++live;}Copy(Copy&&r):n(r.n){r.n=0;++moves;++live;}~Copy(){mark(n);--live;}};
