TEST_F(TranslateTest, CoreV2NonTypeFunctionTemplatesAcceptResolvedScalarArguments) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"unevaluated-size", "template<int N>int f();int main(){return sizeof(f<3>());}"},
      {"unevaluated-noexcept", "template<int N>int f()noexcept;int main(){return noexcept(f<3>());}"},
      {"unused", "template<int N>int f(){return N;}"},
      {"signed", "template<int N>int f(){return N;}int main(){return f<-3>()+3;}"},
      {"bool", "template<bool B>bool f(){return B;}int main(){return !f<true>();}"},
      {"enum", "enum class E:unsigned int{x=3};template<E N>E f(){return N;}int main(){return static_cast<unsigned int>(f<E::x>())-3u;}"},
      {"unsigned-max", "template<unsigned long long N>unsigned long long f(){return N;}int main(){return f<0xffffffffffffffffULL>()!=0xffffffffffffffffULL;}"},
      {"signed-wide", "template<long long N>long long f(){return N;}int main(){return f<-2147483649LL>()!=-2147483649LL;}"},
      {"auto-int", "template<auto N>auto f(){return N;}int main(){return f<3>()-3;}"},
      {"auto-bool", "template<auto N>auto f(){return N;}int main(){return !f<true>();}"},
      {"auto-enum", "enum class E:unsigned int{x=3};template<auto N>auto f(){return N;}int main(){return f<E::x>()!=E::x;}"},
      {"dependent-type", "template<class T,T N>T f(){return N;}int main(){return f<int,3>()-3;}"},
      {"type-default", "template<class T=int,T N>T f(){return N;}int main(){return f<int,3>()-3;}"},
      {"mixed-order", "template<int N,class T>T f(T v){return v+N;}int main(){return f<3>(2)-5;}"},
      {"array-deduction", "template<int N>int f(int(&a)[N]){return N+a[N-1];}int main(){int a[3]={1,2,3};return f(a)-6;}"},
      {"array-size-type", "template<decltype(sizeof(int)) N>int f(int(&a)[N]){return N+a[N-1];}int main(){int a[2]={1,2};return f(a)-4;}"},
      {"written-decltype", "template<decltype(1) N>int f(){return N;}int main(){return f<3>()-3;}"},
      {"written-sizeof", "template<int N>int f(){return N;}int main(){return f<sizeof(int)>()-sizeof(int);}"},
      {"explicit-instantiation", "template<int N>int f(){return N;}template int f<3>();int main(){return f<3>()-3;}"},
      {"explicit-specialization", "template<int N>int f(){return N;}template<>int f<3>(){return 7;}int main(){return f<3>()-7;}"},
      {"redeclared", "template<int N>int f();template<int N>int f(){return N;}int main(){return f<3>()-3;}"},
      {"ordinary-overload", "int f(int n){return n;}template<int N>int f(){return N;}int main(){return f(2)+f<3>()-5;}"},
      {"namespace-import", "namespace A{template<int N>int f(){return N;}}using A::f;int main(){return f<3>()-3;}"},
      {"recursive", "template<int N>int f(){if constexpr(N==0)return 0;else return N+f<N-1>();}int main(){return f<4>()-10;}"},
      {"function-default", "template<int N>int f(int n=N){return n;}int main(){return f<3>()-3;}"},
      {"lazy-function-default", "template<class T,int N>int f(int n=T::missing+N){return n;}int main(){return f<int,3>(4)-4;}"},
      {"static-state", "template<int N>int&f(){static int n=N;return n;}int main(){++f<3>();return f<3>()-4;}"},
      {"static-constant", "template<int N>int f(){static const int n=N;return n;}int main(){return f<3>()-3;}"},
      {"case-label", "template<int N>int f(int n){switch(n){case N:return 3;default:return 1;}}int main(){return f<2>(2)-3;}"},
      {"fixed-local-array", "template<int N>int f(){int a[N]={};a[N-1]=N;return a[N-1];}int main(){return f<3>()-3;}"},
      {"constexpr-declaration", "template<int N>constexpr int f(){return N;}static_assert(f<3>()==3);int main(){return f<3>()-3;}"},
      {"bool-branch", "template<bool B>int f(){if constexpr(B)return 3;else return 4;}int main(){return f<true>()+f<false>()-7;}"},
      {"discarded-dependent-body", "template<int N>int f(){if constexpr(N==0)return 3;else{double d=N;return static_cast<int>(d);}}int main(){return f<0>()-3;}"},
      {"mixed-64", "template<class T0,int N1,class T2,int N3,class T4,int N5,class T6,int N7,class T8,int N9,class T10,int N11,class T12,int N13,class T14,int N15,class T16,int N17,class T18,int N19,class T20,int N21,class T22,int N23,class T24,int N25,class T26,int N27,class T28,int N29,class T30,int N31,class T32,int N33,class T34,int N35,class T36,int N37,class T38,int N39,class T40,int N41,class T42,int N43,class T44,int N45,class T46,int N47,class T48,int N49,class T50,int N51,class T52,int N53,class T54,int N55,class T56,int N57,class T58,int N59,class T60,int N61,class T62,int N63>int f(){return N1;}int main(){return f<int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1>()-1;}"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("nttp-positive-" + Name + ".cpp");
    const auto Output = tmpFile("nttp-positive-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    EXPECT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

TEST_F(TranslateTest, CoreV2NonTypeFunctionTemplatesRetainSourceAndValueBoundaries) {
  const std::vector<std::tuple<std::string, std::string, std::string>> Cases = {
      {"template-template", "template<template<class>class T,int N>int f(){return N;}", "TR0201"},
      {"pointer-parameter", "int n=3;template<int*P>int f(){return *P;}int main(){return f<&n>();}", "TR0201"},
      {"reference-parameter", "int n=3;template<int&N>int f(){return N;}int main(){return f<n>();}", "TR0201"},
      {"function-parameter", "int g(){return 3;}template<int(*F)()>int f(){return F();}int main(){return f<g>();}", "TR0201"},
      {"member-pointer", "struct R{int n;};template<int R::*P>int f(){return 1;}int main(){return f<&R::n>();}", "TR0201"},
      {"auto-pointer", "int n=3;template<auto N>int f(){return 1;}int main(){return f<&n>();}", "TR0201"},
      {"dependent-pointer", "int n=3;template<class T,T N>int f(){return 1;}int main(){return f<int*,&n>();}", "TR0201"},
      {"selected-floating-body", "template<int N>int f(){long double d=N;return static_cast<int>(d);}int main(){return f<3>();}", "TR0201"},
      {"selected-floating-default", "template<int N>int f(int n=static_cast<int>(1.0L)+N){return n;}int main(){return f<3>();}", "TR0201"},
      {"argument-floating-cast", "template<int N>int f(){return N;}int main(){return f<static_cast<int>(1.0L)>();}", "TR0201"},
      {"instantiation-floating-cast", "template<int N>int f(){return N;}template int f<static_cast<int>(1.0L)>();", "TR0201"},
      {"specialization-floating-cast", "template<int N>int f(){return N;}template<>int f<static_cast<int>(1.0L)>(){return 1;}", "TR0201"},
      {"parameter-decltype-float", "template<decltype(static_cast<int>(1.0L)) N>int f(){return N;}int main(){return f<1>();}", "TR0201"},
      {"parameter-decltype-sizeof-float", "template<decltype(sizeof(long double)) N>int f(){return N;}int main(){return f<1>();}", "TR0201"},
      {"argument-sizeof-float", "template<int N>int f(){return N;}int main(){return f<sizeof(long double)>();}", "TR0201"},
      {"oversized-array", "template<int N>int f(){int a[N]={};return a[0];}int main(){return f<65537>();}", "TR0201"},
      {"zero-array", "template<int N>int f(){int a[N];return 0;}int main(){return f<0>();}", "TR0201"},
      {"mixed-65", "template<class T0,int N1,class T2,int N3,class T4,int N5,class T6,int N7,class T8,int N9,class T10,int N11,class T12,int N13,class T14,int N15,class T16,int N17,class T18,int N19,class T20,int N21,class T22,int N23,class T24,int N25,class T26,int N27,class T28,int N29,class T30,int N31,class T32,int N33,class T34,int N35,class T36,int N37,class T38,int N39,class T40,int N41,class T42,int N43,class T44,int N45,class T46,int N47,class T48,int N49,class T50,int N51,class T52,int N53,class T54,int N55,class T56,int N57,class T58,int N59,class T60,int N61,class T62,int N63,class T64>int f(){return N1;}int main(){return f<int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int,1,int>()-1;}", "TR0201"},
      {"nonconstant", "template<int N>int f(){return N;}int main(){int n=3;return f<n>();}", "TR0202"},
      {"narrowing", "template<unsigned char N>int f(){return N;}int main(){return f<256>();}", "TR0202"},
      {"deduction-mismatch", "template<int N>int f(int(&a)[N]){return N;}int main(){int a[2]={};return f<3>(a);}", "TR0202"},
      {"negative-array", "template<int N>int f(){int a[N];return 1;}int main(){return f<-1>();}", "TR0202"},
      {"missing-value-argument", "template<int N>int f(){return N;}int main(){return f<>();}", "TR0202"},
      {"floating-parameter", "template<double N>int f(){return 1;}", "TR0202"},
      {"class-parameter", "struct R{int n;};template<R N>int f(){return 1;}", "TR0202"},
      {"floating-argument", "template<int N>int f(){return N;}int main(){return f<1.0>();}", "TR0202"},
      {"selected", "template<int N>int f();int main(){return f<3>();}", "TR0203"},
      {"explicit-extern", "template<int N>int f();extern template int f<3>();", "TR0203"},
  };
  for (const auto &[Name, Code, Diagnostic] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("nttp-reject-" + Name + ".cpp");
    const auto Output = tmpFile("nttp-reject-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    expectCode(Result, Diagnostic);
    expectNoArtifacts(Output);
  }
  for (const std::string &Code : {"template<int N>int f(){return N;}int main(){return f<3>();}",
                                 "template<auto N>auto f(){return N;}int main(){return f<3>();}"}) {
    const auto Source = tmpFile("nttp-v1.cpp");
    const auto Output = tmpFile("nttp-v1.nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v1", "-o", Output.string()});
    expectCode(Result, "TR0201");
    expectNoArtifacts(Output);
  }
}

TEST_F(TranslateTest, CoreV2FunctionTemplatesPreserveSpecializationIdentityAndLifetime) {
  const auto Source = tmpFile("function_templates.cpp");
  const auto Output = tmpFile("function_templates.nc");
  writeFile(Source, R"cpp(
int defaultCalls=0;
int live=0;
struct DefaultRecord{DefaultRecord(){++live;}~DefaultRecord(){--live;}};
template<class T>int byDefault(T v=T{}){return live;}
template<class T>int refDefault(const T&v=T{}){return live;}
int nextDefault(){return ++defaultCalls;}
struct R { int n; };
struct Trace {
 int*p;int id;
 Trace(int*q,int n):p(q),id(n){*p=*p*10+id;}
 ~Trace(){*p=*p*10+id+4;}
};
template<class T>T identity(T v){return v;}
template<class T>T& alias(T&v){return v;}
template<class T>T* pointer(T*p){return p;}
template<class T=int>T zero(){return T{};}
template<class T>int defaults(T v=T{},int n=nextDefault()){return v+n;}
template<class T>int lazy(T v=T::missing){return v;}
template<class T>T recursive(T n){return n? n+recursive<T>(n-1):0;}
template<class T>T nested(T v){return identity(identity(v));}
template<class T>int sum(T&a){int n=0;for(auto&v:a){++v;n+=v;}return n;}
template<class T>int count(){static int n=0;return ++n;}
template<class T>auto select(int*p){if constexpr(sizeof(T)==sizeof(int)){Trace a(p,1);Trace b(p,2);return *p;}else{return R{9};}}
template<class T>int discarded(){if constexpr(sizeof(T)==sizeof(int))return 3;else return T::missing+static_cast<int>(1.0);}
template<class T>int specialized(T v){return 1;}
template<>int specialized<int>(int v){return 7;}
template<class T>T explicitOnly(T v){return v;}
template int explicitOnly<int>(int);
namespace N { struct Item{int n;};template<class T>int read(const T&t){return t.n;} }
namespace Import { template<class T>T take(T v){return v;} }
using Import::take;
int overload(int v){return 8;}
template<class T>int overload(T v){return 2;}
template<class T,class=typename T::tag>int sfinae(T v){return 4;}
int sfinae(int v){return 5;}
struct Tagged{using tag=int;int n;};
namespace Collision {
 template<class T>int value(T v){static int n=0;return ++n;}
 int early(){return value(1);}
 template<class T>int value(int v){static int n=10;return ++n;}
 int late(){return value<int>(1);}
}
template<class T>auto first(T);
template<class T>auto second(T v){struct Local{T n;};return Local{v};}
template<class T>auto first(T v){return second(v);}
#define PRIMARY(M) template<class T>auto macro(T v)->decltype(v.M){return v.M;}
#define PAIR PRIMARY(a) PRIMARY(b)
struct MacroTypes{int a;bool b;};
PAIR
template int macro<MacroTypes>(MacroTypes);
template bool macro<MacroTypes>(MacroTypes);
int main(){
 if(identity(3)!=3 || identity<int>(4)!=4 || !identity(true) || identity(5u)!=5u)return 1;
 R r{7};if(identity(r).n!=7)return 2;
 int n=3;alias(n)=9;if(n!=9 || pointer(&n)!=&n)return 3;
 if(zero()!=0 || zero<bool>() || zero<R>().n!=0)return 4;
 defaultCalls=0;int a=defaults<int>();int b=defaults(4);if(a!=1 || b!=6 || defaultCalls!=2)return 5;
 if(lazy(7)!=7)return 6;
 if(recursive(4)!=10 || nested(6)!=6)return 7;
 int items[2]={1,2};if(sum(items)!=5 || items[0]!=2 || items[1]!=3)return 8;
 int c=count<int>();int d=count<int>();int e=count<bool>();if(c!=1 || d!=2 || e!=1)return 9;
 int trace=0;int captured=select<int>(&trace);if(captured!=12 || trace!=1265)return 10;
 if(select<unsigned char>(&trace).n!=9 || trace!=1265)return 11;
 if(discarded<int>()!=3)return 12;
 if(specialized(2)!=7 || specialized(true)!=1 || explicitOnly(8)!=8)return 13;
 N::Item item{11};if(read(item)!=11 || take(12)!=12)return 14;
 if(overload(3)!=8 || overload(true)!=2)return 15;
 Tagged tagged{1};if(sfinae(1)!=5 || sfinae(tagged)!=4)return 16;
 int early=Collision::early();int late=Collision::late();int again=Collision::early();if(early!=1 || late!=11 || again!=2)return 17;
 if(first(17).n!=17)return 18;
 int valueAlive=byDefault<DefaultRecord>();if(valueAlive!=1 || live!=0)return 19;
 int referenceAlive=refDefault<DefaultRecord>();if(referenceAlive!=1 || live!=0)return 20;
 return 0;
}
)cpp");
  auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
  ASSERT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  for (const std::string &Optimization : {"-O0", "-O2"}) {
    SCOPED_TRACE(Optimization);
    const auto Executable = tmpFile("function_templates" + Optimization);
    auto Compile = compileGenerated(Output, Executable, Optimization, {"-fno-inline"});
    ASSERT_EQ(Compile.exitCode, 0) << Compile.out << Compile.err;
    auto Run = exec(Executable.string(), {});
    EXPECT_EQ(Run.exitCode, 0) << Run.out << Run.err;
  }
}

TEST_F(TranslateTest, CoreV2FunctionTemplatesAcceptConcreteTypeInstances) {
  const std::vector<std::pair<std::string, std::string>> Cases = {
      {"lazy-namespace-source-nttp-default", "struct Mid{int n;};template<class T,int N=noexcept(Mid())+sizeof(T)>int f()noexcept{T::body();return N;}static_assert(noexcept(f<int>()));"},
      {"lazy-namespace-source-function-default", "struct Mid{int n;};template<class T>int f(int=noexcept(Mid())+sizeof(T))noexcept{T::body();return 0;}static_assert(noexcept(f<int>()));"},
      {"lazy-namespace-source-exception-family", "struct Mid{int n;};template<class T>int f()noexcept(noexcept(Mid())&&sizeof(T)>0){T::body();return 0;}static_assert(noexcept(f<int>()));"},
      {"lazy-namespace-source-operator-default", "struct Mid{int n;};struct R{};template<class T,int N=noexcept(Mid())+sizeof(T)>int operator+(T,T)noexcept{T::body();return N;}static_assert(noexcept(R{}+R{}));"},
      {"lazy-namespace-source-false-result", "struct Mid{int n;};template<class T,int N=noexcept(Mid())+sizeof(T)>int f()noexcept(false){T::body();return N;}static_assert(!noexcept(f<int>()));"},
      {"lazy-namespace-source-selected-type", "struct Mid{int n;};template<class T,int N=noexcept(Mid())+sizeof(T)>int f()noexcept{T::body();return N;}static_assert(__is_same(decltype(f<int>()),int));"},
      {"lazy-namespace-source-parenthesized", "struct Mid{int n;};namespace N{template<class T,int N=noexcept(Mid())+sizeof(T)>int f()noexcept{T::body();return N;}}static_assert(noexcept((N::f<int>)()));"},
      {"lazy-namespace-source-comma-result", "struct Mid{int n;};template<class T,int N=noexcept(Mid())+sizeof(T)>int f()noexcept{T::body();return N;}static_assert(noexcept((0,f<int>())));"},
      {"lazy-namespace-source-unused-default", "template<class T,int N=sizeof(T)>int f(int=T::missing)noexcept{T::body();return N;}static_assert(noexcept(f<int>(3)));"},
      {"lazy-namespace-source-separate-definition", "struct Mid{int n;};template<class T,int N=noexcept(Mid())+sizeof(T)>int f()noexcept;template<class T,int N>int f()noexcept{T::body();return N;}static_assert(noexcept(f<int>()));"},
      {"declared-signature-free-operator", "struct R{};template<class T,int N=sizeof(T)>int operator+(T,T)noexcept(N>0);static_assert(noexcept(R{}+R{}));"},
      {"declared-signature-default-family", "struct Mid{int n;};template<class T>int f(int=noexcept(Mid())+sizeof(T))noexcept;static_assert(noexcept(f<int>()));"},
      {"declared-signature-false-default-family", "struct Mid{int n;};template<class T,int N=noexcept(Mid())+sizeof(T)>int f()noexcept(false);static_assert(!noexcept(f<int>()));"},
      {"declared-signature-deduced", "template<class T>T f(T);static_assert(__is_same(decltype(f(1)),int));"},
      {"declared-signature-noexcept", "template<class T>T f(T)noexcept;static_assert(noexcept(f(1)));"},
      {"declared-signature-noexcept-false", "template<class T>T f(T)noexcept(false);static_assert(!noexcept(f(1)));"},
      {"declared-signature-type-default", "template<class T=int>T f()noexcept;static_assert(__is_same(decltype(f()),int)&&noexcept(f()));"},
      {"declared-signature-value-default", "template<class T,int N=sizeof(T)>T f(T,int=N)noexcept(N==sizeof(T));static_assert(noexcept(f(1)));"},
      {"declared-signature-explicit-default-unused", "template<class T>int f(int=T::missing)noexcept;static_assert(noexcept(f<int>(3)));"},
      {"declared-signature-packs", "template<class...T>int f(T...)noexcept(sizeof...(T)==2);static_assert(noexcept(f(1,2u))&&!noexcept(f()));"},
      {"declared-signature-qualified-parenthesis", "namespace N{template<class T>T f(T)noexcept;}static_assert(noexcept((N::f)(1))&&__is_same(decltype((N::f)(1)),int));"},
      {"declared-signature-reference-overload", "template<class T>T&& probe(int);template<class T>T probe(long);template<class T>decltype(probe<T>(0)) value()noexcept{static_assert(!__is_same(T,T));}static_assert(__is_same(decltype(value<int>()),int&&)&&__is_same(decltype(value<int&>()),int&));"},
      {"declared-signature-void-fallback", "template<class T>T&& probe(int);template<class T>T probe(long);template<class T>decltype(probe<T>(0)) value()noexcept{static_assert(!__is_same(T,T));}static_assert(__is_same(decltype(value<void>()),void)&&noexcept(value<void>()));"},
      {"declared-signature-array-function", "template<class T>T&& probe(int);template<class T>T probe(long);template<class T>decltype(probe<T>(0)) value()noexcept{static_assert(!__is_same(T,T));}using A=int[2];using F=int(int);static_assert(__is_same(decltype(value<A>()),A&&)&&__is_same(decltype(value<F>()),F&));"},
      {"declared-signature-default-effects", "int calls;int next()noexcept{++calls;return 3;}template<class T>int f(int=next())noexcept;static_assert(noexcept(f<int>()));int main(){return calls;}"},
      {"declared-signature-ordinary-default-source", "struct Mid{int n;};template<class T,int N=noexcept(Mid())+sizeof(T)>T f()noexcept;static_assert(noexcept(f<int>()));"},
      {"declared-signature-materialized-specialization", "int calls;template<class T>T f(T)noexcept;template<>unsigned f<unsigned>(unsigned n)noexcept{++calls;return n+1;}static_assert(noexcept(f(1)));int main(){auto v=f(3u);return v-4+calls-1;}"},
      {"noexcept-signature-only", "template<class T>T f(T v){return v;}int main(){return noexcept(f(1));}"},
      {"sizeof-signature-only", "template<class T>T f(T v){return v;}int main(){return sizeof(f(1));}"},
      {"deduced", "template<class T>T id(T v){return v;}int main(){return id(3)-3;}"},
      {"explicit", "template<class T>T id(T v){return v;}int main(){return id<int>(3)-3;}"},
      {"default-type", "template<class T=int>T zero(){return T{};}int main(){return zero();}"},
      {"default-redecl", "template<class T=int>T zero();template<class U>U zero(){return U{};}int main(){return zero();}"},
      {"default-dependent-type", "template<class T,class U=T>U convert(T v){return v;}int main(){return convert(3)-3;}"},
      {"void-type", "template<class T>int tag(){return 3;}int main(){return tag<void>()-3;}"},
      {"reference-type", "template<class T>T id(T v){return v;}int main(){int n=3;id<int&>(n)=4;return n-4;}"},
      {"const-pointer", "template<class T>T* id(T*p){return p;}int main(){const int n=3;return *id(&n)-3;}"},
      {"record-return", "struct R{int n;};template<class T>T id(T v){return v;}int main(){return id(R{3}).n-3;}"},
      {"range-array", "template<class T>int sum(T&a){int n=0;for(auto&x:a)n+=x;return n;}int main(){int a[2]={1,2};return sum(a)-3;}"},
      {"constexpr", "template<class T>constexpr T add(T n){return n+1;}static_assert(add(2)==3,\"value\");int main(){return add(3)-4;}"},
      {"constexpr-discarded", "template<class T>int f(){if constexpr(sizeof(T)==sizeof(int))return 3;else return T::missing;}int main(){return f<int>()-3;}"},
      {"constexpr-return-types", "struct R{int n;};template<class T>auto f(){if constexpr(sizeof(T)==sizeof(int))return 3;else return R{4};}int main(){return f<int>()+f<bool>().n-7;}"},
      {"unused-floating-pattern", "template<class T>double f(T v){double x=1.0;return x+v;}int main(){return 0;}"},
      {"discarded-floating-branch", "template<class T>int f(){if constexpr(sizeof(T)==sizeof(int))return 3;else return static_cast<int>(1.0);}int main(){return f<int>()-3;}"},
      {"lazy-invalid-default", "template<class T>int f(T v=T::missing){return v;}int main(){return f(3)-3;}"},
      {"lazy-floating-default", "template<class T>int f(T v=static_cast<T>(1.0)){return v;}int main(){return f(3)-3;}"},
      {"selected-default", "template<class T>int f(T v=T{}){return v;}int main(){return f<int>();}"},
      {"specialization", "template<class T>int f(T v){return 1;}template<>int f<int>(int v){return 3;}int main(){return f(1)-3;}"},
      {"specialization-forward", "template<class T>int f(T);template<>int f<int>(int);template<>int f<int>(int v){return v;}int main(){return f(3)-3;}"},
      {"explicit-definition", "template<class T>T f(T v){return v;}template int f<int>(int);"},
      {"extern-defined", "template<class T>T f(T v){return v;}extern template int f<int>(int);template int f<int>(int);int main(){return f(3)-3;}"},
      {"candidate-without-body", "template<class T>int f(T v){double unused=1.0;return 2;}int f(int v){return 3;}int main(){return f(1)-3;}"},
      {"sfinae", "template<class T,class=typename T::tag>int f(T v){return 2;}int f(int v){return 3;}int main(){return f(1)-3;}"},
      {"nested-redeclare", "template<class T>auto first(T);template<class T>auto second(T n){struct R{T n;};return R{n};}template<class T>auto first(T n){return second(n);}int main(){return first(3).n-3;}"},
      {"namespace-import", "namespace N{template<class T>T f(T v){return v;}}namespace A=N;using A::f;int main(){return f(3)-3;}"},
      {"inline-namespace", "namespace N{inline namespace V{template<class T>T f(T v){return v;}}}int main(){return N::f(3)-3;}"},
      {"static-identity", "template<class T>int f(){static int n=0;return ++n;}int main(){int a=f<int>();int b=f<int>();int c=f<bool>();return a+b+c-4;}"},
      {"function-reference", "template<class T>T&& move(T&v){return static_cast<T&&>(v);}int main(){int n=3;int&&r=move(n);r=4;return n-4;}"},
      {"noexcept-resolved", "template<class T>int f(T v)noexcept(sizeof(T)==sizeof(int)){return v;}int main(){return f(3)-3;}"},
      {"static-template-pattern", "template<class T>int f(){static int n=3;return n;}"},
      {"import-template-pattern", "namespace N{template<class T>T f(T n){return n;}}using N::f;"},
      {"constexpr-template-pattern", "template<class T>int f(){if constexpr(sizeof(T)==4)return 1;else return 0;}"},
      {"default-template-pattern", "template<class T>int f(T n=T{}){return 1;}"},
      {"exception-template-pattern", "template<class T>int f(T&t)noexcept(noexcept(t.get())){return 1;}"},
      {"type-parameter-limit-64", "template<class T0,class T1,class T2,class T3,class T4,class T5,class T6,class T7,class T8,class T9,class T10,class T11,class T12,class T13,class T14,class T15,class T16,class T17,class T18,class T19,class T20,class T21,class T22,class T23,class T24,class T25,class T26,class T27,class T28,class T29,class T30,class T31,class T32,class T33,class T34,class T35,class T36,class T37,class T38,class T39,class T40,class T41,class T42,class T43,class T44,class T45,class T46,class T47,class T48,class T49,class T50,class T51,class T52,class T53,class T54,class T55,class T56,class T57,class T58,class T59,class T60,class T61,class T62,class T63>int f(){return 1;}int main(){return f<int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int,int>()-1;}"},
      {"record-default-lifetime", "int live=0;struct R{R(){++live;}~R(){--live;}};template<class T>int f(T v=T{}){return live;}int main(){int n=f<R>();return n-1+live;}"},
      {"reference-default-lifetime", "int live=0;struct R{R(){++live;}~R(){--live;}};template<class T>int f(const T&v=T{}){return live;}int main(){int n=f<R>();return n-1+live;}"},
  };
  for (const auto &[Name, Code] : Cases) {
    SCOPED_TRACE(Name);
    const auto Source = tmpFile("function_templates-positive-" + Name + ".cpp");
    const auto Output = tmpFile("function_templates-positive-" + Name + ".nc");
    writeFile(Source, Code);
    auto Result = translate(Source, {"--profile", "cpp-core-v2", "-o", Output.string()});
    EXPECT_EQ(Result.exitCode, 0) << Result.out << Result.err;
  }
}

