  const int& const_alias = std::apply(&Box::value, const_boxes);
  if (&const_alias != &const_boxes[0].value) return 20;
  int&& rvalue_alias = std::apply(&Box::take, static_cast<Boxes&&>(boxes));
  rvalue_alias = 24;
